import SchemaBuilder from '@pothos/core';
import { pluginName } from './plugin';

const builder = new SchemaBuilder({
  plugins: [pluginName],
  optionInRootOfConfig: true,
  nestedOptionsObject: { exampleOption: 'Configured object' },
});
const User = builder.objectRef<{ name: string }>('User').implement({
  optionOnObject: true,
  fields: (t) => ({
    name: t.exposeString('name'),
    removeMe: t.string({ resolve: () => 'Hidden' }),
  }),
});
const Choice = builder.enumType('Choice', {
  values: { KEEP: { value: 'keep' }, REMOVE: { value: 'removeMe' } },
});
const Input = builder.inputType('ExampleInput', {
  fields: (t) => ({ keep: t.string(), removeMe: t.string() }),
});
const Custom = builder.buildCustomObject();
const custom: { custom: 'shape' } = { custom: 'shape' };
builder.queryType({
  fields: (t) => ({
    user: t.field({ type: User, resolve: () => ({ name: 'Alex' }) }),
    custom: t.field({ type: Custom, resolve: () => custom }),
    choice: t.field({ type: Choice, resolve: (): 'keep' => 'keep' }),
  }),
});
builder.mutationType({
  fields: (t) => ({
    update: t.boolean({
      customMutationFieldOption: true,
      args: { input: t.arg({ type: Input }) },
      resolve: () => true,
    }),
  }),
});
// Build twice: runUnique runs the preparation callback only once.
builder.toSchema({ customBuildTimeOptions: false });
export const schema = builder.toSchema({ customBuildTimeOptions: true });

import type {
  FieldNullability,
  InputFieldMap,
  ObjectRef,
  SchemaTypes,
  TypeParam,
} from '@pothos/core';
import type { HooksPlugin } from './plugin';

declare global {
  namespace PothosSchemaTypes {
    interface Plugins<Types extends SchemaTypes> {
      architectureHooks: HooksPlugin<Types>;
    }
    interface SchemaBuilderOptions<Types extends SchemaTypes> {
      optionInRootOfConfig?: boolean;
      nestedOptionsObject?: { exampleOption: string };
    }
    interface BuildSchemaOptions<Types extends SchemaTypes> {
      customBuildTimeOptions?: boolean;
    }
    interface ObjectTypeOptions<Types extends SchemaTypes, Shape> {
      optionOnObject?: boolean;
    }
    interface MutationFieldOptions<
      Types extends SchemaTypes,
      Type extends TypeParam<Types>,
      Nullable extends FieldNullability<Type>,
      Args extends InputFieldMap,
      ResolveReturnShape,
    > {
      customMutationFieldOption?: boolean;
    }
    interface SchemaBuilder<Types extends SchemaTypes> {
      buildCustomObject: () => ObjectRef<Types, { custom: 'shape' }>;
    }
  }
}

import './global-types';
import SchemaBuilder, {
  BasePlugin,
  type PothosEnumValueConfig,
  type PothosInputFieldConfig,
  type PothosOutputFieldConfig,
  type PothosTypeConfig,
  type SchemaTypes,
} from '@pothos/core';
import { GraphQLSchema } from 'graphql';

const schemaBuilderProto = SchemaBuilder.prototype as PothosSchemaTypes.SchemaBuilder<SchemaTypes>;
schemaBuilderProto.buildCustomObject = function buildCustomObject() {
  return this.objectRef<{ custom: 'shape' }>('CustomObject').implement({
    fields: (t) => ({ custom: t.exposeString('custom') }),
  });
};

export class HooksPlugin<Types extends SchemaTypes> extends BasePlugin<Types> {
  onTypeConfig(typeConfig: PothosTypeConfig) {
    const label = this.builder.options.nestedOptionsObject?.exampleOption;
    const rootOption = this.builder.options.optionInRootOfConfig;
    const buildOption = this.options.customBuildTimeOptions;
    if (typeConfig.kind === 'Object' && typeConfig.pothosOptions.optionOnObject) {
      return {
        ...typeConfig,
        description: `${label}; root=${rootOption}; build=${buildOption}`,
      };
    }
    return typeConfig;
  }

  onOutputFieldConfig(fieldConfig: PothosOutputFieldConfig<Types>) {
    if (fieldConfig.name === 'removeMe') {
      return null;
    }
    if (fieldConfig.kind === 'Mutation' && fieldConfig.pothosOptions.customMutationFieldOption) {
      return { ...fieldConfig, description: 'Configured mutation' };
    }
    return fieldConfig;
  }

  onInputFieldConfig(fieldConfig: PothosInputFieldConfig<Types>) {
    return fieldConfig.name === 'removeMe' ? null : fieldConfig;
  }

  onEnumValueConfig(valueConfig: PothosEnumValueConfig<Types>) {
    return valueConfig.value === 'removeMe' ? null : valueConfig;
  }

  beforeBuild() {
    this.runUnique('architecture-added-field', () => {
      console.log('Preparing schema once per builder');
    });
  }

  afterBuild(schema: GraphQLSchema) {
    return new GraphQLSchema({
      ...schema.toConfig(),
      description: 'Schema transformed after build',
    });
  }
}

export const pluginName = 'architectureHooks';
SchemaBuilder.registerPlugin(pluginName, HooksPlugin);

